    ('story', 0, 180, 'Your money tells a story.', 'Bank statements. Card bills. So many transactions. Where does your money actually go?', 'Scattered statement slips converge into one orderly ledger.', ['Your money', 'tells a story.'], ['C01']),
    ('introduce', 180, 390, 'Meet LocalFinance.', 'Meet Local Finance. A private, offline workspace for your Indian bank accounts and credit cards.', 'Shield mark resolves into a computer containing an organized financial workspace.', ['Meet', 'LocalFinance.', 'Your private money workspace.'], ['C01', 'C02']),
    ('import', 390, 690, 'Bring your statements.', 'Start with a supported PDF, CSV, or Excel statement. Preview the transactions, then import. Local Finance reads and organizes the records on your computer.', 'Statement file descends into local preview; preview rows turn into imported ledger rows.', ['01 / IMPORT', 'Statements in.', 'Clarity out.', 'Preview → Import → Local ledger'], ['C02', 'C03']),
    ('organize', 690, 960, 'Make it yours.', 'Rules help categorize spending. Add tags and notes. Reimport the same statement without duplicates. Your edits stay.', 'Uncategorized fictional merchant row becomes categorized; tags and notes persist through reimport stamp.', ['02 / ORGANIZE', 'A ledger that', 'stays yours.', 'Your edits survive reimport.'], ['C04', 'C05']),
